import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type LoadingAnimationProps = Record<string, any>;

const LoadingAnimation: React.FC<LoadingAnimationProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 5,
  loadingText = "Loading",
  primaryColor = "#8e8e93",
  spinnerSize = 160,
  speedMultiplier = 1,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const durationFrames = durationInSeconds * fps;

  // Entrance and Exit animations
  const entranceOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const exitOpacity = interpolate(frame, [durationFrames - 15, durationFrames], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const globalOpacity = entranceOpacity * exitOpacity;

  const entranceScale = spring({
    fps,
    frame,
    config: { damping: 14, stiffness: 100 },
  });

  // Structural constants
  const textContainerMargin = spinnerSize * 0.4;
  const fontSize = Math.max(20, spinnerSize * 0.15);
  const ticksCount = 12;

  // Render 12 discrete ticks forming the Apple-style spinner
  const tickElements = Array.from({ length: ticksCount }).map((_, i) => {
    // Calculate which tick is fully lit based on frame and speed
    const activeTick = Math.floor((frame / (fps / speedMultiplier)) * ticksCount) % ticksCount;
    
    // Calculate distance from the active tick to create a fading tail
    const distance = (ticksCount + activeTick - i) % ticksCount;
    
    // Opacity fades out as distance increases from the active tick
    const tickOpacity = Math.max(0.15, 1 - (distance / ticksCount) * 0.85);

    return (
      <div
        key={i}
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          transform: `rotate(${i * 30}deg)`,
          transition: "none",
        }}
      >
        <div
          style={{
            position: "absolute",
            top: 0,
            left: "50%",
            transform: "translateX(-50%)",
            width: spinnerSize * 0.08,
            height: spinnerSize * 0.26,
            backgroundColor: primaryColor,
            borderRadius: spinnerSize * 0.04,
            opacity: tickOpacity,
            transition: "none",
          }}
        />
      </div>
    );
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        opacity: globalOpacity,
        transition: "none",
      }}
    >
      <div
        style={{
          position: "relative",
          width: spinnerSize,
          height: spinnerSize,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${entranceScale})`,
          transition: "none",
        }}
      >
        {tickElements}
      </div>

      {loadingText && (
        <div
          style={{
            marginTop: textContainerMargin,
            fontSize: fontSize,
            fontWeight: 500,
            color: primaryColor,
            letterSpacing: "0.02em",
            opacity: entranceOpacity,
            transform: `scale(${entranceScale}) translateY(${interpolate(entranceScale, [0, 1], [20, 0])}px)`,
            transition: "none",
            display: "flex",
            alignItems: "center",
          }}
        >
          {loadingText}
        </div>
      )}
    </AbsoluteFill>
  );
};

export default LoadingAnimation;